export const ConfirmDelete: Story = {
  parameters: { docs: { source: { type: "code" } } },
  render: () => {
    const [files, setFiles] = useState<Array<FileItem>>([]);
    const [open, setOpen] = useState<boolean>(false);
    const [id, setId] = useState<number>();

    const handleDeleteFile = () => {
      const fileList = [...files];
      const index = fileList.findIndex((file) => file.id === id);
      fileList.splice(index, 1);
      setFiles(fileList);
      setOpen(false);
    };
    const confirmDelete = (id: number) => {
      setOpen(true);
      setId(id);
    };

    return (
      <div>
        <Dialog open={open} onClose={() => setOpen(false)}>
          <DialogHeader>
            {" "}
            Are you sure you want to delete this file?
          </DialogHeader>
          <DialogContent>
            <p>Clicking on delete will delete the uploaded file.</p>
          </DialogContent>
          <DialogActions>
            <Button variant="secondary" onClick={() => setOpen(false)}>
              Cancel
            </Button>
            <Button variant="error" onClick={handleDeleteFile}>
              Delete
            </Button>
          </DialogActions>
        </Dialog>

        <FileUpload
          multiple
          dragAndDrop
          onAdd={(newFiles) => setFiles([...newFiles, ...files])}
          onDelete={confirmDelete}
          files={files}
        />
      </div>
    );
  },
};

export const Controlled: Story = {
  parameters: { docs: { source: { type: "code" } } },
  render: () => {
    const [files, setFiles] = useState<Array<FileItem>>([]);
    const [uploadComplete, setUploadComplete] = useState(false);

    const handleDeleteFile = (id: number) => {
      let fileList = [...files];
      let index = fileList.findIndex((file) => file.id === id);
      fileList.splice(index, 1);
      setFiles(fileList);
    };

    const handleAddFile = (newFiles: Array<FileItem>) => {
      setUploadComplete(false);
      setFiles([...newFiles, ...files]);
    };

    // simulating server files upload through setInterval
    useEffect(() => {
      if (files.length > 0 && !uploadComplete) {
        const interval = setInterval(() => {
          let successCount = 0;
          const updatedFiles: FileItem[] = files.map((file) => {
            if (file.status === "added") {
              return { ...file, status: "uploading", percentage: 10 };
            } else if (file.status === "uploading" && file.percentage <= 100) {
              return { ...file, percentage: file.percentage + 10 };
            } else if (file.status === "error") {
              return { ...file, status: "error" };
            } else {
              successCount++;
              return { ...file, status: "success" };
            }
          });

          setUploadComplete(successCount === updatedFiles.length);
          setFiles(updatedFiles);
        }, 500);
        return () => clearInterval(interval);
      }
    }, [files, uploadComplete]);

    return (
      <FileUpload
        dragAndDrop
        multiple
        onAdd={handleAddFile}
        onDelete={handleDeleteFile}
        files={files}
      />
    );
  },
};

